export const COSTS=[{wood:12,fibre:4},{wood:10,fibre:4},{wood:6,fibre:8}];
export function freshState(){return{version:1,x:-1,z:3,wood:0,fibre:0,food:2,health:100,energy:100,time:0,stage:0,cut:[],pickupTimers:Array(24).fill(0),won:false};}
export function validateSave(s){const n=freshState();if(!s||s.version!==1)return n;for(const k of ['wood','fibre','food','health','energy','time','stage','x','z'])if(Number.isFinite(s[k]))n[k]=s[k];for(const k of ['wood','fibre','food'])n[k]=Math.max(0,Math.floor(n[k]));n.health=Math.max(0,Math.min(100,n.health));n.energy=Math.max(0,Math.min(100,n.energy));n.stage=Math.max(0,Math.min(3,Math.floor(n.stage)));n.time=Math.max(0,Math.min(480,n.time));if(Math.hypot(n.x/10.9,n.z/9.2)>1){n.x=-1;n.z=3;}n.cut=Array.isArray(s.cut)?[...new Set(s.cut.filter(i=>Number.isInteger(i)&&i>=0&&i<22))]:[];n.pickupTimers=n.pickupTimers.map((_,i)=>Number.isFinite(s.pickupTimers?.[i])?Math.min(55,Math.max(0,s.pickupTimers[i])):0);n.won=s.won===true&&n.stage===3;return n;}
export function canBuild(s){const cost=COSTS[s.stage];return Boolean(cost&&s.wood>=cost.wood&&s.fibre>=cost.fibre);}
export function buildStage(s){if(!canBuild(s))return false;const c=COSTS[s.stage];s.wood-=c.wood;s.fibre-=c.fibre;s.stage++;return true;}
